(()=>{
 const source=document.querySelector('.toolbar'),panel=document.querySelector('.panel.ad');if(!source||!panel)return;
 const box=document.createElement('section');box.className='ad-controls';box.setAttribute('aria-label','AD脑图就近操作');const title=document.createElement('h3');title.textContent='调整当前脑图';box.appendChild(title);
 const clone=source.cloneNode(true),pairs=[];clone.querySelectorAll('[id]').forEach(copy=>{const original=document.getElementById(copy.id);copy.id='ad-control-'+copy.id;pairs.push([original,copy]);if(copy.tagName==='BUTTON')copy.addEventListener('click',()=>{original.click();sync();});else for(const type of ['input','change'])copy.addEventListener(type,()=>{original.value=copy.value;original.checked=copy.checked;original.dispatchEvent(new Event(type,{bubbles:true}));sync();});});box.appendChild(clone);
 const topics=document.createElement('div');topics.className='ad-topics';const labels=['脑沟','海马','脑室','海马旁回','颞叶','顶叶','额叶','后扣带区'];document.querySelectorAll('[data-topic]').forEach((original,i)=>{const copy=document.createElement('button');copy.type='button';copy.textContent=labels[i]||original.textContent;copy.addEventListener('click',()=>{original.click();sync();});pairs.push([original,copy]);topics.appendChild(copy);});box.appendChild(topics);panel.insertBefore(box,panel.querySelector('.caption'));
 function sync(){for(const [original,copy] of pairs){copy.className=original.className;copy.disabled=original.disabled;if(copy.tagName==='BUTTON'){if(!original.hasAttribute('data-topic'))copy.textContent=original.textContent;copy.setAttribute('aria-pressed',String(original.classList.contains('active')));}else{copy.value=original.value;copy.checked=original.checked;}}}
 const observer=new MutationObserver(sync);observer.observe(source,{subtree:true,attributes:true,childList:true,characterData:true});document.querySelectorAll('[data-topic]').forEach(x=>observer.observe(x,{attributes:true}));for(const type of ['click','input','change','pointerup'])document.addEventListener(type,()=>requestAnimationFrame(sync));sync();
})();
